from pathlib import Path
root=Path(__file__).resolve().parent
p=root/'app.js'
s=p.read_text()

def replace_function(source, name, next_name, replacement):
    start=source.index('function '+name+'(')
    end=source.index(next_name,start)
    return source[:start]+replacement.strip()+'\n'+source[end:]

# Compact room picker: separate vector illustration thumbnails, one column only
s=s.replace("const ROOM_IMAGE_URLS=Object.fromEntries(names.map(r=>[r,`assets/rooms/${r}.webp`]));", "const ROOM_IMAGE_URLS=Object.fromEntries(names.map(r=>[r,`assets/room_icons/${r}.svg`]));")
s=replace_function(s,'roomsHTML','function climateHTML(',r'''function roomsHTML(){return `<section class="side-panel rooms-v13" aria-label="Rooms"><div class="side-kicker">SPACES</div><div class="side-titleline"><h2>Rooms</h2><small>4 zones</small></div><div class="rooms-v13-list">${names.map(r=>{const t=targetStyle(state.targets[r]);return `<button class="room-pick" data-room="${r}" aria-label="Control ${rooms[r].label}"><img class="room-pick-icon" src="${ROOM_IMAGE_URLS[r]}" alt="" draggable="false"><span class="room-pick-copy"><b>${rooms[r].label}</b><small>${state.co2[r]} ppm · ${state.lights[r]>0?'Lights on':'Lights off'}</small></span><strong style="color:${t.color}">${fmt(state.temps[r])}°</strong><span class="room-pick-chevron">›</span></button>`}).join('')}</div><div class="rooms-v13-foot"><span class="foot-pulse"></span> Select a room or tap the house</div></section>`}''')

s=replace_function(s,'climateHTML','function energyHTML(',r'''function climateHTML(){return `<section class="side-panel climate-v13" aria-label="Climate controls"><div class="side-kicker">AIR MANAGEMENT</div><div class="side-titleline"><h2>Climate</h2><small>${state.ventilation?'Running':'Off'}</small></div><div class="measure-hero"><strong>${flow()}</strong><span>m³/h</span></div><div class="measure-hint">Supply airflow</div><div class="vent-modes" role="group" aria-label="Fan mode">${['Auto','Eco','Manual'].map(m=>`<button class="${state.ventMode===m&&!boostActive()?'active':''}" data-action="ventMode" data-mode="${m}">${m}</button>`).join('')}</div>${state.ventMode==='Manual'&&!boostActive()?`<div class="manual-v13"><input class="range" data-range="manual" type="range" min="100" max="300" step="10" value="${state.manualFlow}" aria-label="Manual supply airflow"><output id="manualReadout">${state.manualFlow} m³/h</output></div>`:''}<div class="thin-switch"><span>${ico('fan')} Fan</span><button class="switch ${state.ventilation?'on':''}" data-action="toggleVent">${state.ventilation?'On':'Off'}</button></div><div class="thin-switch"><span>${ico('air')} Recovery</span><button class="switch ${state.recovery?'on':''}" data-action="toggleRecovery">${state.recovery?'On':'Off'}</button></div><button class="btn primary full-boost" data-action="boost">${boostActive()?`Stop boost · ${boostLeft()}m`:'Boost · 30 min'}</button><p class="inline-note">${boostActive()?'Previous fan setting resumes afterward':'Central ventilation · simulated'}</p></section>`}''')

s=replace_function(s,'energyHTML','const actionLabels=',r'''function energyHTML(){const fan=state.ventilation?flow()*.0012:0,heat=state.heating?.75:0,water=state.water?.20:0,light=names.reduce((a,r)=>a+state.lights[r],0)*.0007,base=.15,max=Math.max(.1,fan+heat+water+light+base);const parts=[{name:'Heating',val:heat,color:'#ffc67e'},{name:'Air',val:fan,color:'#69e8e6'},{name:'Water',val:water,color:'#81bbf6'},{name:'Other',val:light+base,color:'#8198a9'}];return `<section class="side-panel energy-v13" aria-label="Energy controls"><div class="side-kicker">BUILDING LOAD</div><div class="side-titleline"><h2>Energy</h2><small>Estimate</small></div><div class="measure-hero"><strong>${fmt(power())}</strong><span>kW</span></div><div class="measure-hint">Current demand</div><div class="energy-strips" aria-label="Estimated load composition">${parts.map(p=>`<span style="width:${(p.val/max*100).toFixed(1)}%;background:${p.color}" title="${p.name}: ${fmt(p.val)} kW"></span>`).join('')}</div><div class="energy-mini-legend">${parts.slice(0,3).map(p=>`<span><i style="background:${p.color}"></i>${p.name}</span>`).join('')}</div><div class="thin-switch"><span>${ico('temp')} Heating</span><button class="switch ${state.heating?'on':''}" data-action="toggleHeat">${state.heating?'On':'Off'}</button></div><div class="thin-switch"><span>${ico('water')} Hot water</span><button class="switch ${state.water?'on':''}" data-action="toggleWater">${state.water?'On':'Off'}</button></div><div class="energy-fan-reading"><span>${ico('fan')} Ventilation</span><strong>${flow()} <small>m³/h</small></strong></div><p class="inline-note">Illustrative data · no energy meter</p></section>`}''')

s=replace_function(s,'routinesHTML','function moreHTML(',r'''function routinesHTML(){return `<section class="side-panel routines-v13" aria-label="Scheduled routines"><div class="side-kicker">AUTOMATION</div><div class="side-titleline"><h2>Routines</h2><button class="routine-add" data-action="newRoutine" ${state.routines.length>=3?'disabled':''}>${ico('plus')} Add</button></div><div class="routine-list-v13">${state.routines.length?state.routines.map(rt=>`<div class="routine-item"><span class="routine-time">${rt.time}</span><span class="routine-label"><b>${rooms[rt.room].label}</b><small>${actionLabels[rt.action]}</small></span><button class="routine-toggle-v13 ${rt.enabled?'on':''}" data-action="toggleRoutine" data-id="${rt.id}" aria-label="${rt.enabled?'Pause':'Enable'} ${rooms[rt.room].label} routine">${rt.enabled?'On':'Off'}</button><button class="routine-edit-v13" data-action="editRoutine" data-id="${rt.id}" aria-label="Edit ${rooms[rt.room].label} routine">···</button></div>`).join(''):'<div class="routines-empty">No routines yet</div>'}</div><div class="routines-foot">Daily · runs while app is open</div></section>`}''')

# Keep advanced features but fit all settings without scroll
s=replace_function(s,'moreHTML','function roomHTML(',r'''function moreHTML(){const t=state.moreTab;const rows=t==='system'?`<div class="more-status-row"><span>${ico('shield')} Alarm</span><strong>${state.alarm?'Armed':'Disarmed'}</strong></div><div class="more-status-row"><span>${ico('check')} Doors</span><strong>${state.locked?'Locked':'Unlocked'}</strong></div><p class="inline-note">Use the header to change security states.</p>`:t==='display'?`<div class="thin-switch"><span>Motion</span><button class="switch ${state.motion?'on':''}" data-action="toggleMotion">${state.motion?'On':'Off'}</button></div><div class="thin-switch"><span>Building FX</span><button class="switch ${state.effects?'on':''}" data-action="toggleEffects">${state.effects?'On':'Off'}</button></div><div class="more-status-row"><span>Background</span><strong>${sequenceMode==='frames'?`${sequenceUrls.length} frames`:sequenceMode==='video'?'Video':'Image'}</strong></div><div class="mini-asset-actions"><button class="btn" data-action="replaceArt">Image</button><button class="btn" data-action="importSequence">Frames</button><button class="btn" data-action="resetArt">Reset</button></div><div class="thin-switch"><span>FX on imports</span><button class="switch ${state.mediaOverlay?'on':''}" data-action="toggleMediaOverlay" ${artworkUrl?'':'disabled'}>${state.mediaOverlay?'On':'Off'}</button></div>`:`<div class="more-status-row"><span>High CO₂ test</span><button class="btn" data-action="co2Demo">Trigger</button></div><div class="more-status-row"><span>Outdoor weather</span><button class="btn" data-action="weather">Refresh</button></div><div class="more-status-row"><span>Reset demo</span><button class="btn negative" data-action="resetConfirm">Reset</button></div>`;return `<section class="side-panel more-v13" aria-label="More settings"><div class="side-kicker">CONTROLLER</div><div class="side-titleline"><h2>More</h2><small>Demo</small></div><div class="more-tabs-v13">${[['system','Status'],['display','Display'],['demo','Tests']].map(([k,l])=>`<button class="${t===k?'active':''}" data-action="moreTab" data-tab="${k}">${l}</button>`).join('')}</div>${rows}</section>`}''')

# left panel room control, same geometry as Home panel
s=replace_function(s,'roomHTML','function fixtureDialog(',r'''function roomHTML(r){const {label,blinds}=rooms[r],t=state.targets[r],v=state.lights[r],b=state.blinds[r]||0;const btext=b===100?'Closed':b===0?'Open':`${b}% closed`;return `<aside class="room-side" aria-label="${label} controls"><div class="room-side-header"><span class="side-kicker">ROOM CONTROL</span><button class="room-exit" data-action="closeRoom" aria-label="Whole building">${ico('close')}</button></div><h2>${label}</h2><div class="room-data"><strong>${fmt(state.temps[r])}°</strong><span>${state.co2[r]} ppm<br>${state.occupied[r]?'Occupied':'Vacant'}</span></div><div class="room-mini-nav">${names.map(k=>`<button class="${r===k?'active':''}" data-room="${k}" aria-label="Select ${rooms[k].label}">${({bedroom:'Bed',living:'Living',kitchen:'Kitchen',utility:'Utility'})[k]}</button>`).join('')}</div><div class="room-action-block"><div class="room-action-top"><span>Target</span><strong>${fmt(t)}°</strong></div><div class="room-action-buttons two"><button data-action="tempDown" data-room="${r}" aria-label="Decrease ${label} temperature">${ico('minus')}</button><button data-action="tempUp" data-room="${r}" aria-label="Increase ${label} temperature">${ico('plus')}</button></div></div><div class="room-action-block"><div class="room-action-top"><span>${ico('light')} Lights</span><button data-action="fixtureDialog" data-room="${r}" aria-label="Choose ${label} light fixtures">Details ›</button></div><div class="room-action-buttons room-light-buttons"><button data-action="lightsOff" data-room="${r}" class="${v===0?'active':''}">Off</button><input type="range" class="range" min="0" max="100" step="5" data-range="lights" data-room="${r}" value="${v}" aria-label="${label} light brightness"><button data-action="lightsOn" data-room="${r}" class="${v>0?'active':''}">On</button></div></div><div class="room-action-block last"><div class="room-action-top"><span>${ico('blinds')} Blinds</span><small>${blinds?btext:'Not fitted'}</small></div>${blinds?`<div class="room-action-buttons three"><button data-action="blindOpen" data-room="${r}" class="${b===0?'active':''}">Open</button><button data-action="blindHalf" data-room="${r}" class="${b===50?'active':''}">50%</button><button data-action="blindClose" data-room="${r}" class="${b===100?'active':''}">Close</button></div>`:''}</div></aside>`}''')

